// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        address initialCEO = c.ceoAddress();
        vm.assume(actor != address(0));
        vm.assume(actor != initialCEO);

        // A non-CEO successfully claims the CEO role.
        vm.prank(actor);
        c.DrugDealer();

        // Rule: after the transfer, the PREVIOUS CEO no longer passes the
        // access check on DrugDealer — it must revert for them now.
        bool ok = true;
        vm.prank(initialCEO);
        try c.DrugDealer() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}

