// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        // WIDE domain: no assumption excluding the initial CEO. The fuzzer may
        // pick any address, including the one that satisfies the require, so the
        // success branch is reachable and the difference becomes observable.
        vm.assume(actor != address(0));

        // Snapshot the CEO before the call (public getter).
        bool changed;
        try c.DrugDealer() {
            changed = true;
        } catch {
            changed = false;
        }

        // General rule: whenever DrugDealer succeeds, the caller must become the
        // new CEO (the mutant never updates ceoAddress, so any caller whose call
        // succeeds without the getter reflecting them breaks the rule).
        assertTrue(!changed || c.ceoAddress() == actor);
    }
}

