pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        address currentCeo = c.ceoAddress();
        vm.prank(currentCeo);
        c.DrugDealer();
        assertEq(c.ceoAddress(), currentCeo, "ceoAddress must stay msg.sender (= current CEO) after DrugDealer by CEO");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function runTest(uint256 drugs) public {
        require(address(this).balance >= 0);
        c.seedMarket{value: 0}(drugs);
        assert(c.initialized());
    }

    receive() external payable {}
    fallback() external payable {}
}

