    C c;
    constructor(C _c) { c = _c; }
    function runTest(uint256 drugs) public {
        require(c.marketDrugs() == 0, "market must be unseeded");
        c.seedMarket{value: 0}(drugs);
        c.getFreeKilo();
        assert(c.getMyKilo() == c.STARTING_KILOS());
    }
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function runTest() public {
        // On P, DrugDealer reverts for any caller that is not the current ceoAddress.
        // On M, it succeeds for any caller and reassigns ceoAddress.
        bool reverted = false;
        try c.DrugDealer() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }
    receive() external payable {}
    fallback() external {}
}

contract InvMutTest {

    C c;

    constructor(C _c) {
        c = _c;
    }

    function test() public {
        // Any caller (here, this test contract, which is not the CEO)
        // must be unable to execute DrugDealer: it must revert.
        (bool ok, ) = address(c).call(abi.encodeWithSelector(C.DrugDealer.selector));
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

