contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool reverted;
        bool success;
        (success, ) = address(c).call(abi.encodeWithSignature("DrugDealer()"));
        if (success) { reverted = false; } else { reverted = true; }
        assert(reverted == (caller != c.ceoAddress()));
    }
    receive() external payable {}
}

